def add(ia,ib,il,ih,mask,val,cs):
 a=(ib-ia)/len(A); l=(ih-il)/len(L); k=int(np.sum((mask>>np.arange(9))&1));p=a*l*2.**(-k)
 if p<.008 or p>.95:return
