def cov(idx):
 u=rules[idx];pi=pp[idx];a=ar[idx];l=lr[idx]
 ai=np.maximum(0,np.minimum(rules[:,1],u[1])-np.maximum(rules[:,0],u[0]))/len(A)
 li=np.maximum(0,np.minimum(rules[:,3],u[3])-np.maximum(rules[:,2],u[2]))/len(L)
 inter=rules[:,4]&u[4];union=rules[:,4]|u[4]
 conflict=(rules[:,5]&inter)!=(u[5]&inter)
 kk=np.sum((union[:,None]>>np.arange(9))&1,axis=1)
